const B=window.Broadcast;B.prepare(state);
const broadcastBaseRoute=route,broadcastBaseShell=adminShell;
const broadcastLabels={draft:'内容確認待ち',development:'開発用・未送信',cancelled:'停止済み・未送信'};
adminShell=function(section,body){return broadcastBaseShell(section,body).replace('</nav>','<a href="#/admin/broadcast" class="'+(section==='broadcast'?'active':'')+'">一斉メール</a></nav>');};
mailPage=function(){return adminShell('mail','<div class="panel"><h2>開発メール（実送信なし）</h2><p><a class="btn" href="#/admin/broadcast">申込者への一斉メールを作成</a></p>'+state.mail.slice().reverse().map(m=>'<details><summary>'+esc(m.subject)+' ／ '+esc(m.to||state.people.find(p=>p.id===m.personId)?.email||'')+'</summary><p>宛先：'+esc(m.to||state.people.find(p=>p.id===m.personId)?.email||'未設定')+' ／ '+esc(m.status||'開発用・未送信')+'</p><pre class="message-body">'+esc(m.body)+'</pre></details>').join('')+'</div>');};
function broadcastPage(id=0){let body='<p class="notice">この公開サンプルは、このブラウザーだけに保存します。実際のメールは送信せず、他の端末とも共有しません。</p>';const b=state.broadcasts.find(b=>b.id===id);if(id&&!b)return adminShell('broadcast','下書きがありません。');if(b){body+='<p><a href="#/admin/broadcast">← 新規作成・履歴</a></p><div class="panel"><h2>'+esc(b.subject)+'</h2><p>'+broadcastLabels[b.status]+' ／ '+(b.target==='all'?'全申込者（欠席・取消を含む）':'参加予定の申込者のみ')+' ／ '+b.audience.recipients.length+'件 ／ 除外 '+b.audience.excluded.length+'件</p><pre class="message-body">'+esc(b.body)+'</pre><p>宛先ごとに個別のメールを作成します。</p>'+(b.status==='draft'?'<form id="broadcastQueue" data-id="'+id+'"><label><input type="checkbox" name="confirm" value="yes" required> 内容と対象人数を確認しました。</label><p class="error-text"></p><button class="btn">開発メールへ登録（実送信なし）</button></form>':'')+'</div><div class="panel"><h3>対象の宛先</h3>'+table(['名前','メールアドレス','状態'],b.audience.recipients.map(r=>[esc(r.name),esc(r.email),broadcastLabels[b.status]]))+ (b.audience.excluded.length?'<h3>除外した宛先</h3>'+table(['見本ID','理由'],b.audience.excluded.map(r=>[r.id,esc(r.reason)])):'')+'</div>'+(b.status!=='cancelled'?'<div class="panel"><form id="broadcastCancel" data-id="'+id+'">'+field('reason','停止理由')+'<p class="error-text"></p><button class="btn btn-outline">この一斉メールを停止</button></form></div>':'');}else{body+='<div class="panel"><div class="eyebrow">ANNOUNCEMENT</div><h2>申込者へ、一斉にお知らせ。</h2><p>開催予定の変更などを、登録されたメールアドレス宛に連絡します。</p><form id="broadcastPreview">'+select('target','対象',[['all','全申込者（欠席・取消を含む）'],['active','参加予定の申込者のみ']],'all')+field('subject','件名')+'<label class="field">本文<textarea name="body" rows="8" maxlength="10000" required></textarea></label><p class="error-text"></p><button class="btn">内容と対象人数を確認する</button></form></div><div class="panel"><h3>作成・登録履歴</h3>'+table(['作成日','件名','宛先数','状況'],state.broadcasts.slice().reverse().map(b=>[esc(date(b.created)),'<a href="#/admin/broadcast/'+b.id+'">'+esc(b.subject)+'</a>',b.audience.recipients.length,broadcastLabels[b.status]]))+'</div>';}return adminShell('broadcast',body);}
route=function(){B.prepare(state);const p=(location.hash.slice(1)||'/').split('/').filter(Boolean);if(p[0]==='admin'&&p[1]==='broadcast'&&organizer()){main.innerHTML=broadcastPage(Number(p[2]||0));window.scrollTo(0,0);return;}broadcastBaseRoute();};
window.removeEventListener('hashchange',broadcastBaseRoute);window.addEventListener('hashchange',route);
document.addEventListener('submit',ev=>{const f=ev.target;if(!f.id.startsWith('broadcast'))return;ev.preventDefault();ev.stopImmediatePropagation();const d=Object.fromEntries(new FormData(f));try{const uid=current()?.id,id=Number(f.dataset.id);if(f.id==='broadcastPreview'){const b=change(s=>B.preview(s,d,uid));location.hash='/admin/broadcast/'+b.id;}else if(f.id==='broadcastQueue')change(s=>B.queue(s,id,d.confirm,uid));else if(f.id==='broadcastCancel')change(s=>B.cancel(s,id,d.reason,uid));route();toast('開発用の内容と操作履歴を保存しました');}catch(e){f.querySelector('.error-text').textContent=e.message;}},true);
route();
